def _glom_match(target, spec, scope):
    if isinstance(spec, type):
        if not isinstance(target, spec):
            raise TypeMatchError(type(target), spec)
        return target
    elif isinstance(spec, dict):
        return _handle_dict(target, spec, scope)
    elif isinstance(spec, (list, tuple, set, frozenset)):
        if not isinstance(target, type(spec)):
            raise TypeMatchError(type(target), type(spec))
        if isinstance(spec, (set, frozenset)):
            if len(spec) == 0:
                if len(target) != 0:
                    raise MatchError("{0!r} does not match {1!r}", target, spec)
                return target
            if len(spec) != 1:
                raise ValueError("set/frozenset specs must have exactly one element")
            (item_spec,) = spec
            for item in target:
                scope[glom](item, item_spec, scope)
            return target
        else:
            if len(spec) == 0:
                if len(target) != 0:
                    raise MatchError("{0!r} does not match {1!r}", target, spec)
                return target
            if isinstance(spec, list):
                if len(spec) != 1:
                    raise ValueError("list specs must have exactly one element")
                (item_spec,) = spec
                result = []
                for item in target:
                    result.append(scope[glom](item, item_spec, scope))
                return result
            else:  # tuple
                if len(spec) != len(target):
                    raise MatchError("{0!r} does not match {1!r}", target, spec)
                result = []
                for item, item_spec in zip(target, spec):
                    result.append(scope[glom](item, item_spec, scope))
                return type(spec)(result)
    elif callable(spec):
        try:
            if not spec(target):
                raise MatchError("{0!r} did not satisfy {1!r}", target, spec)
        except MatchError:
            raise
        except Exception as e:
            raise MatchError("{0!r} did not satisfy {1!r}: {2!r}", target, spec, e)
        return target
    else:
        if target != spec:
            raise MatchError("{0!r} does not match {1!r}", target, spec)
        return target
